import { readFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, it, expect } from 'vitest';
import { generatePrd } from './prd';
import { CASES, prdPayload, prdDigest } from '../../test-support/prdCharacterizationCases';

const fixturesDir = join(dirname(fileURLToPath(import.meta.url)), 'prd.characterization.fixtures');

/**
 * SHA-256 digests of JSON.stringify({slug,title,prompt,markdown}).
 *
 * Regenerated by `npx tsx scripts/regen-characterization.mts`, which runs the
 * real generator — never by hand. Last regenerated when feature derivation began
 * reading the prompt, which changes every document that describes a real
 * capability — and deliberately leaves a plain CRUD prompt's digest unchanged.
 * Full golden payloads live in `prd.characterization.fixtures/*.json`.
 */
const EXPECTED_DIGESTS: Readonly<Record<string, string>> = {
  'dashboard-auth-two-entities': '3c5c08d159fc1b4eaa46f76566eb7090e26ab2b18c7e5cc0dd704438fe58b98c',
  'mobile-no-auth-two-entities': 'fd108b21b5db4398b1d2ba6025051643b27726954e42f68c740449e98f94eca1',
  'marketplace-auth-scoped': '91fa625e87bf7b0cc89c458cf8a9243e40648fb6efec4d99b9c16ec4c80d59f8',
  'empty-entities-no-auth': '64c43361eba2701ebab109aaddefdfccab991e8a6af345331cd05c6d0a87baa2',
  'long-prompt-many-entities': 'e88f3ea2ed0bbe6d83cd9ecbd81494b8413929c57df53f20e64b76a36e98ba86'
};

describe('generatePrd characterization (byte-identical output)', () => {
  for (const c of CASES) {
    it(`matches golden output for ${c.id}`, () => {
      const prd = generatePrd(c.answers, c.cost);
      const payload = prdPayload(prd);
      const digest = prdDigest(prd);

      const fixturePath = join(fixturesDir, `${c.id}.json`);
      expect(existsSync(fixturePath), `missing fixture ${fixturePath}`).toBe(true);
      const golden = readFileSync(fixturePath, 'utf8');
      expect(payload).toBe(golden);
      expect(digest).toBe(EXPECTED_DIGESTS[c.id]);
    });
  }

  it('covers at least five varied inputs', () => {
    expect(CASES.length).toBeGreaterThanOrEqual(5);
    const ids = new Set(CASES.map((c) => c.id));
    expect(ids.size).toBe(CASES.length);
  });
});
